[CmdletBinding()] param([string]$SqlServer='SL646104',$BauSource,$PostgresTarget)
$ErrorActionPreference='Stop'; Import-Module (Join-Path $PSScriptRoot 'EprLocalAutomation/EprLocalAutomation.psm1'); if(-not $env:EPR_BAU_SQL_PASSWORD){$env:EPR_BAU_SQL_PASSWORD=[Environment]::GetEnvironmentVariable('EPR_BAU_SQL_PASSWORD','User')}; if(-not $BauSource -and -not $env:EPR_BAU_SQL_PASSWORD){throw 'EPR_BAU_SQL_PASSWORD is required.'}; $source=if($BauSource){$BauSource}else{New-BauSource -SqlServer $SqlServer -SqlUser reader}; $target=if($PostgresTarget){$PostgresTarget}else{New-PostgresTarget -PostgresHost localhost}; $workspace=New-RunWorkspace; try { & (Get-Module EprLocalAutomation) {param($s,$t,$w) Invoke-ReviewedGroupAddressMigration -Source $s -Target $t -Workspace $w -FixtureFile 'seed/fixtures/t19r-group-addresses.json'} $source $target $workspace } finally { Remove-RunWorkspace -Path $workspace }
